def choose_move(observation):
    def sg(v):
        return (v > 0) - (v < 0)

    def is_num(x):
        return isinstance(x, (int, float)) and not isinstance(x, bool)

    def as_pair(x):
        if isinstance(x, (list, tuple)) and len(x) >= 2 and is_num(x[0]) and is_num(x[1]):
            return [int(x[0]), int(x[1])]
        if isinstance(x, dict):
            for a, b in (("x", "y"), ("row", "col"), ("r", "c")):
                if a in x and b in x and is_num(x.get(a)) and is_num(x.get(b)):
                    return [int(x.get(a)), int(x.get(b))]
        return None

    def find_pairs(obj, out, seen, limit=256):
        if len(out) >= limit:
            return
        oid = id(obj)
        if oid in seen:
            return
        seen.add(oid)
        p = as_pair(obj)
        if p is not None:
            out.append(p)
            return
        if isinstance(obj, dict):
            for k, v in obj.items():
                if isinstance(v, (dict, list, tuple)):
                    find_pairs(v, out, seen, limit)
        elif isinstance(obj, (list, tuple)):
            for v in obj:
                if isinstance(v, (dict, list, tuple)):
                    find_pairs(v, out, seen, limit)

    def get_pos(d):
        if not isinstance(d, dict):
            return None
        for k in ("self", "agent", "player", "me", "unit", "avatar", "agent_state"):
            v = d.get(k)
            if isinstance(v, dict):
                for kk in ("pos", "position", "loc", "location", "coord", "coordinates"):
                    p = as_pair(v.get(kk))
                    if p is not None:
                        return p
                p = as_pair(v)
                if p is not None:
                    return p
        for k in ("pos", "position", "loc", "location", "coord", "coordinates", "xy"):
            p = as_pair(d.get(k))
            if p is not None:
                return p
        return None

    def get_int_field(d, keys, default=0):
        if not isinstance(d, dict):
            return default
        for k in keys:
            v = d.get(k)
            if is_num(v):
                return int(v)
        return default

    def score_dir(me, tgt, away=False):
        dx = tgt[0] - me[0]
        dy = tgt[1] - me[1]
        if away:
            dx, dy = -dx, -dy
        return [sg(dx), sg(dy)]

    obs = observation if isinstance(observation, dict) else {}
    me = get_pos(obs) or [0, 0]

    # Gather candidate pairs from common fields and recursively from the observation.
    all_pairs = []
    for key in ("resources", "resource", "targets", "target", "goals", "goal", "food", "items",
                "opponents", "opponent", "enemies", "enemy", "agents", "players",
                "territory", "tiles", "cells", "objects", "entities"):
        v = obs.get(key)
        if isinstance(v, (dict, list, tuple)):
            find_pairs(v, all_pairs, set())

    # Also scan shallowly for nested coordinate-bearing dicts.
    for k, v in obs.items():
        if isinstance(v, (dict, list, tuple)):
            find_pairs(v, all_pairs, set())

    # Remove self if present.
    candidates = []
    for p in all_pairs:
        if p[0] != me[0] or p[1] != me[1]:
            candidates.append(p)

    # Task hints.
    task = ""
    for k in ("task", "mode", "game", "scenario", "name", "type"):
        v = obs.get(k)
        if isinstance(v, str):
            task = v.lower()
            break

    # Separate plausible targets/threats by field names.
    resources = []
    threats = []
    territory = []
    for key in ("resources", "resource", "targets", "target", "goals", "goal", "food", "items"):
        v = obs.get(key)
        if isinstance(v, (list, tuple)):
            find_pairs(v, resources, set())
        elif isinstance(v, dict):
            find_pairs(v, resources, set())
    for key in ("opponents", "opponent", "enemies", "enemy", "agents", "players"):
        v = obs.get(key)
        if isinstance(v, (list, tuple)):
            find_pairs(v, threats, set())
        elif isinstance(v, dict):
            find_pairs(v, threats, set())
    for key in ("territory", "tiles", "cells"):
        v = obs.get(key)
        if isinstance(v, (list, tuple, dict)):
            find_pairs(v, territory, set())

    # Clean duplicates
    def dedup(ps):
        seen = set()
        out = []
        for p in ps:
            t = (p[0], p[1])
            if t not in seen:
                seen.add(t)
                out.append(p)
        return out

    resources = dedup(resources)
    threats = dedup(threats)
    territory = dedup(territory)
    candidates = dedup(candidates)

    # Identify likely "safe" and "objective" directions.
    move = [0, 0]

    # Resource collection: go to nearest resource.
    if resources or "resource" in task or "collect" in task or "pickup" in task:
        pool = resources if resources else candidates
        if pool:
            best = min(pool, key=lambda p: abs(p[0] - me[0]) + abs(p[1] - me[1]))
            move = score_dir(me, best, away=False)

    # Pursuit/evasion: if threats exist, decide from score/distance hints.
    elif "pursuit" in task or "evasion" in task or "chase" in task or "hunt" in task:
        my_score = get_int_field(obs, ("score", "my_score", "points", "health"), 0)
        opp_score = get_int_field(obs, ("opponent_score", "enemy_score"), 0)
        if threats:
            nearest = min(threats, key=lambda p: abs(p[0] - me[0]) + abs(p[1] - me[1]))
            if my_score >= opp_score:
                move = score_dir(me, nearest, away=False)
            else:
                move = score_dir(me, nearest, away=True)
        elif candidates:
            move = score_dir(me, min(candidates, key=lambda p: abs(p[0] - me[0]) + abs(p[1] - me[1])), away=False)

    # Territory control: move toward territory/targets, else toward center-like nearest info.
    elif "territory" in task or "control" in task or territory:
        pool = territory if territory else resources if resources else candidates
        if pool:
            best = min(pool, key=lambda p: abs(p[0] - me[0]) + abs(p[1] - me[1]))
            move = score_dir(me, best, away=False)

    # Generic fallback: chase closest objective if any, otherwise avoid nearest threat.
    else:
        if resources:
            best = min(resources, key=lambda p: abs(p[0] - me[0]) + abs(p[1] - me[1]))
            move = score_dir(me, best, away=False)
        elif territory:
            best = min(territory, key=lambda p: abs(p[0] - me[0]) + abs(p[1] - me[1]))
            move = score_dir(me, best, away=False)
        elif threats:
            nearest = min(threats, key=lambda p: abs(p[0] - me[0]) + abs(p[1] - me[1]))
            move = score_dir(me, nearest, away=True)
        elif candidates:
            best = min(candidates, key=lambda p: abs(p[0] - me[0]) + abs(p[1] - me[1]))
            move = score_dir(me, best, away=False)

    dx = max(-1, min(1, int(move[0])))
    dy = max(-1, min(1, int(move[1])))

    # Small deterministic tie-break: prefer horizontal if both zero and there is info.
    if dx == 0 and dy == 0:
        seed = (me[0] * 31 + me[1] * 17 + len(resources) * 13 + len(threats) * 7 + len(territory) * 5) % 4
        if seed == 1:
            dx = 1
        elif seed == 2:
            dx = -1
        elif seed == 3:
            dy = 1

    return [dx, dy]

